use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression given a store (mapping from variable names to integers).
/// Variables not found in the store are mapped to -1.
pub fn eval(e: &Exp, store: &HashMap<String, i32>) -> i32 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(e1, e2) => eval(e1, store) + eval(e2, store),
        Exp::Mult(e1, e2) => eval(e1, store) * eval(e2, store),
    }
}

/// Perform a local peephole optimization at the root node of the expression.
/// Does NOT recurse into sub-expressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(left, right) => {
            match (&*left, &*right) {
                // multiplication by 0 -> 0
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),

                // multiplication by 1 -> the other operand
                (Exp::Const(1), _) => (*right).clone(),
                (_, Exp::Const(1)) => (*left).clone(),

                // constant folding: both sides constants -> product
                (Exp::Const(c1), Exp::Const(c2)) => Exp::Const(c1 * c2),

                // no optimization
                _ => Exp::Mult(left, right),
            }
        }
        Exp::Plus(left, right) => {
            match (&*left, &*right) {
                // addition by 0 -> the other operand
                (Exp::Const(0), _) => (*right).clone(),
                (_, Exp::Const(0)) => (*left).clone(),

                // constant folding: both sides constants -> sum
                (Exp::Const(c1), Exp::Const(c2)) => Exp::Const(c1 + c2),

                // no optimization
                _ => Exp::Plus(left, right),
            }
        }
        // constants and variables remain unchanged
        _ => e,
    }
}

